import base64
import zlib
import pygame

ART = {'smith': (68, 58, '', ''), 'imp': (39, 33, '3d3d3d272727571c27891e2bc42430080808ffa214ffc825424c6e131313657392ffffffc7cfdd2a2f4e14161f92a1b9000000', ''), 'knight': (54, 35, '', ''), 'fire': (50, 45, 'ff5000ed7614ffa214ffc825ffeb57', ''), 'dwarf': (52, 49, 'ffffffc7cfdd657392424c6e92a1b98a4836131313bf6f4a2727270069aaf6ca9fe69c690098dc391f215d2c28891e2bc42430571c272a2f4e00396dffa214ffc825ed7614', ''), 'golem': (70, 74, 'b4b4b48585855d5d5d3d3d3dffa214ffc825636162804b38b27b59512b28ffffff', ''), 'boulder': (24, 24, '28282e60606496969ac8c8cc78787c46464c50382c', ''), 'demon': (159, 121, '2727273d3d3d131313571c27891e2bc424300d00180e001a0a0004120013ffc8255d5d5d858585b4b4b4391f211a19328e251d657392c7cfdd92a1b9ed7614ffffff424c6effa214302b4b5d2c282a2f4effeb57fbf2360e00106639310d0007362f51170c12edab50e074380f030f1c121cff0000b10001fc2d01f1af152f0018040023', '')}
FRAMES = {'smith': 7, 'imp': 7, 'knight': 8, 'fire': 8, 'dwarf': 10, 'golem': 15, 'boulder': 8, 'demon': 21}
XCACHE = {}


def extra_frame(kind, fr, recolor=None):
  """Pixel-art frames: smith, imp, knight, dwarf, golem (12 walk + 3 throw), boulder, fire (breath fireballs, face right), demon (0-7 idle, 8-13 slash, 14 hit flash, 15-20 death)."""
  fr %= FRAMES[kind]
  key = (kind, fr, recolor)
  s = XCACHE.get(key)
  if s is None:
    w, h, pal, data = ART[kind]
    if (kind, 'raw') not in XCACHE:
      XCACHE[(kind, 'pal')] = [None] + [tuple(int(pal[i + k:i + k + 2], 16) for k in (0, 2, 4)) for i in range(0, len(pal), 6)]
      XCACHE[(kind, 'raw')] = zlib.decompress(base64.b64decode(data))
    raw, p = XCACHE[(kind, 'raw')], XCACHE[(kind, 'pal')]
    s = pygame.Surface((w, h), pygame.SRCALPHA)
    base = fr * w * h
    for i in range(w * h):
      v = raw[base + i]
      if v:
        s.set_at((i % w, i // w), (recolor(p[v]) if recolor else p[v]) + (255,))
    XCACHE[key] = s
  return s
